style.css:
/* ===========================
   Pinterest Cozy Theme
   Light Pink + Sage Green
   =========================== */

/* Background */
body {
    background: #FFF8FB !important;
    color: #5f5f5f !important;
}

/* Main content */
div,
section,
main {
    background: #FFF8FB !important;
}

/* Top navigation */
header {
    background: #F6FFF7 !important;
    border-bottom: 2px solid #D8EACD !important;
}

/* Search bar */
input,
textarea {
    background: #ffffff !important;
    border: 2px solid #D8EACD !important;
    border-radius: 20px !important;
    color: #555 !important;
}

/* Buttons */
button {
    background: #F8C8DC !important;
    color: white !important;
    border-radius: 20px !important;
    transition: 0.3s;
}

button:hover {
    background: #C8E6C9 !important;
}

/* Cards/Pins */
[data-test-id="pin"] {
    border-radius: 22px !important;
    overflow: hidden;
    box-shadow: 0 6px 18px rgba(0,0,0,.08);
    transition: .25s;
}

[data-test-id="pin"]:hover {
    transform: translateY(-4px);
    box-shadow: 0 10px 24px rgba(0,0,0,.15);
}

/* Rounded images */
img {
    border-radius: 18px !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 12px;
}

::-webkit-scrollbar-track {
    background: #FFF4F8;
}

::-webkit-scrollbar-thumb {
    background: #C9DFC5;
    border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
    background: #A8C8A0;
}

/* Links */
a {
    color: #A87CA0 !important;
}

a:hover {
    color: #7AA37A !important;
}

/* Sidebar */
aside {
    background: #F7FFF8 !important;
}

/* Selected items */
[aria-selected="true"] {
    background: #FADCE8 !important;
    border-radius: 18px;
}

/* Hide ads */
[data-test-id*="ad"],
[data-grid-item-type="ad"],
div[data-promoted] {
    display: none !important;
}

/* Softer animations */
* {
    transition: background-color .25s ease,
                color .25s ease,
                border-color .25s ease;
}
